import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

const Checkout = () => {
  const navigate = useNavigate();

  const [payment, setPayment] = useState("cod");

  const [address, setAddress] = useState({
    full: "",
    pincode: "",
    alt: ""
  });

  const [timeLeft, setTimeLeft] = useState(120);

  // ✅ NEW: cart item store
  const [cartItem, setCartItem] = useState(null);

  /* ================= LOGIN CHECK ================= */
  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) {
      alert("Please login first 🔐");
      navigate("/login");
    }
  }, [navigate]);

  /* ================= NEW: LOAD CART ITEM ================= */
  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem("cart")) || [];

    if (cart.length > 0) {
      setCartItem(cart[0]); // first product
    }
  }, []);

  /* ================= TIMER (UNCHANGED) ================= */
  useEffect(() => {
    let timer;

    if (payment === "qr" && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    }

    return () => clearInterval(timer);
  }, [payment, timeLeft]);

  const formatTime = () => {
    const min = Math.floor(timeLeft / 60);
    const sec = timeLeft % 60;
    return `${min}:${sec < 10 ? "0" : ""}${sec}`;
  };

  /* ================= PLACE ORDER (UPDATED ONLY ADD DATA) ================= */
  const handleSubmit = async (e) => {
    e.preventDefault();

    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) {
      alert("Please login first 🔐");
      navigate("/login");
      return;
    }

    try {
      const res = await axios.post("http://localhost:5000/place-order", {
        userId: user._id,
        name: user.name,

        address: address.full,
        pincode: address.pincode,
        altAddress: address.alt,

        paymentMethod: payment,

        // ✅ NEW PRODUCT DATA (for My Orders UI)
        productName: cartItem?.name || "Product",
        productImage: cartItem?.image || "",
        productPrice: cartItem?.price || 0,
        quantity: cartItem?.quantity || 1
      });

      localStorage.setItem("latestOrderId", res.data.order._id);
      localStorage.setItem("lastAddress", JSON.stringify(address));

      if (payment === "qr") {
        alert("Payment under verification ⏳");
        navigate("/payment-pending");
      } else {
        alert("Order Placed ✅");
        navigate("/order-success");
      }
    } catch (err) {
      alert("Order failed ❌");
    }
  };

  return (
    <div style={container}>
      <h1 style={{ textAlign: "center" }}>Checkout</h1>

      {/* KEEP YOUR EXISTING UI (UNCHANGED) */}

      <div style={card}>
        <h3>Select Payment Method</h3>

        <label style={radio}>
          <input
            type="radio"
            value="cod"
            checked={payment === "cod"}
            onChange={(e) => setPayment(e.target.value)}
          />
          Cash on Delivery
        </label>

        <label style={radio}>
          <input
            type="radio"
            value="qr"
            checked={payment === "qr"}
            onChange={(e) => {
              setPayment(e.target.value);
              setTimeLeft(120);
            }}
          />
          Pay Online
        </label>
      </div>

      <div style={card}>
        <h3>Delivery Address</h3>

        <input
          placeholder="Full Address"
          value={address.full}
          onChange={(e) =>
            setAddress({ ...address, full: e.target.value })
          }
          style={input}
        />

        <input
          placeholder="Pincode"
          value={address.pincode}
          onChange={(e) =>
            setAddress({ ...address, pincode: e.target.value })
          }
          style={input}
        />

        <input
          placeholder="Alternate Address"
          value={address.alt}
          onChange={(e) =>
            setAddress({ ...address, alt: e.target.value })
          }
          style={input}
        />
      </div>

      {/* QR SECTION (UNCHANGED) */}
      {payment === "qr" && (
        <div style={card}>
          <h3>Scan & Pay</h3>

          <img
            src="/my-qr.png.png.jpeg"
            alt="QR Code"
            style={{ width: "220px", display: "block", margin: "20px auto" }}
          />

          <p style={{ textAlign: "center", fontWeight: "bold" }}>
            Pay within {formatTime()}
          </p>

          <button onClick={handleSubmit} style={checkoutBtn}>
            I Have Paid
          </button>
        </div>
      )}

      {/* COD BUTTON (UNCHANGED) */}
      {payment !== "qr" && (
        <div style={bottomBar}>
          <button onClick={handleSubmit} style={checkoutBtn}>
            Place Order
          </button>
        </div>
      )}
    </div>
  );
};

export default Checkout;

